__global__ void fused_multiply_lrelu_kernel(const float* input, float* output, float multiplier, float negative_slope, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] * multiplier;
        output[idx] = (val > 0) ? val : val * negative_slope;
    }
}

torch::Tensor fused_multiply_lrelu_rocm(torch::Tensor input, float multiplier, float negative_slope) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_multiply_lrelu_kernel, 
        dim3(num_blocks), 
        dim3(block_size), 
        0, 
        at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        multiplier, 
        negative_slope, 
        size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cmath>

__global__ void fused_act_kernel(const float* x, const float* add_vec, float* out, int out_features, int total) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    int j = idx % out_features;
    float v = x[idx] + add_vec[j];

    // Swish
    v *= 1.0f / (1.0f + expf(-v));

    // Tanh
    v = tanhf(v);

    // GELU approx
    v = 0.5f * v * (1.0f + tanhf(0.7978845608028654f * (v + 0.044715f * v*v*v)));

    // Hardtanh
    out[idx] = fminf(fmaxf(v, -1.0f), 1.0f);
}

torch::Tensor fused_activation_rocm(torch::Tensor x, torch::Tensor add_vec) {
    TORCH_CHECK(x.is_cuda() && add_vec.is_cuda(), "Tensors must be on GPU");
    TORCH_CHECK(x.is_contiguous() && add_vec.is_contiguous(), "Requires contiguous tensors");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(add_vec.dim() == 1, "add_vec must be 1D");
    TORCH_CHECK(x.size(1) == add_vec.size(0), "Dimension mismatch");

    auto out = torch::empty_like(x);
    int total = x.numel();
    int out_feat = x.size(1);

    int block = 256;
    int grid = (total + block - 1) / block;

    hipStream_t stream = at::hip::getCurrentHIPStream().stream();
    fused_act_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(), add_vec.data_ptr<float>(), 
        out.data_ptr<float>(), out_feat, total
    );

    return out;
}

