#define BLOCK_SIZE 256

__device__ __inline__ float gelu_activation(float x) {
    return 0.5f * x * (1.0f + erff(x * 0.7071067811865475f));
}

__global__ void fused_gelu_group_norm_kernel(
    const float* input, float* output,
    const float* gamma, const float* beta,
    int B, int C, int H, int W,
    int G, float eps) {

    extern __shared__ float smem[];
    int batch = blockIdx.y;
    int group = blockIdx.x;
    int ch_per_group = C / G;
    int spatial_size = H * W;

    int tid = threadIdx.x;
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = tid; i < ch_per_group * spatial_size; i += blockDim.x) {
        int c = i / spatial_size;
        int s = i % spatial_size;
        int idx = batch * C * spatial_size + (group * ch_per_group + c) * spatial_size + s;
        float val = input[idx];
        float gelu_val = gelu_activation(val);
        sum += gelu_val;
        sum_sq += gelu_val * gelu_val;
    }

    smem[tid] = sum;
    smem[tid + blockDim.x] = sum_sq;
    __syncthreads();

    for (int offset = blockDim.x/2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            smem[tid] += smem[tid + offset];
            smem[tid + blockDim.x] += smem[tid + offset + blockDim.x];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = smem[0] / (ch_per_group * spatial_size);
        float var = (smem[blockDim.x] / (ch_per_group * spatial_size)) - mean * mean;
        float inv_std = rsqrtf(var + eps);

        for (int i = 0; i < ch_per_group * spatial_size; ++i) {
            int c = i / spatial_size;
            int s = i % spatial_size;
            int idx = batch * C * spatial_size + (group * ch_per_group + c) * spatial_size + s;
            float val = input[idx];
            float gelu_val = gelu_activation(val);
            output[idx] = (gelu_val - mean) * inv_std * gamma[group * ch_per_group + c] + beta[group * ch_per_group + c];
        }
    }
}

torch::Tensor fused_gelu_group_norm_rocm(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, int num_groups, float eps) {
    auto B = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);

    auto output = torch::empty_like(input);
    dim3 grid(num_groups, B);
    size_t shared_mem = 2 * BLOCK_SIZE * sizeof(float);

    hipLaunchKernelGGL(fused_gelu_group_norm_kernel, 
        grid, BLOCK_SIZE, shared_mem, 
        c10::hip::getCurrentHIPStream(),
        input.data_ptr<float>(), output.data_ptr<float>(),
        gamma.data_ptr<float>(), beta.data_ptr<float>(),
        B, C, H, W, num_groups, eps
    );

    return output;
}

