__global__ void argmax_kernel(const float* input, int64_t* output, int reduction_size, int stride_d, int step_d, int output_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= output_size) return;

    int base_idx = (idx / step_d) * reduction_size * stride_d + (idx % step_d);

    float max_val = -INFINITY;
    int max_idx = 0;

    for (int i=0; i<reduction_size; i++) {
        float val = input[base_idx + i*stride_d];
        if (val > max_val) {
            max_val = val;
            max_idx = i;
        }
        else if (val == max_val && i < max_idx) {
            max_idx = i;
        }
    }

    output[idx] = max_idx;
}

torch::Tensor argmax_rocm(torch::Tensor input, int dim) {
    auto sizes = input.sizes();
    int64_t reduction_size = sizes[dim];
    int64_t stride_d = input.stride(dim);

    int64_t step_d = 1;
    for (int i=dim+1; i<sizes.size(); i++) {
        step_d *= sizes[i];
    }

    auto output_shape = input.sizes().vec();
    output_shape.erase(output_shape.begin() + dim);
    auto output = torch::empty(output_shape, torch::TensorOptions().dtype(torch::kLong).device(input.device()));

    int64_t output_size = output.numel();
    const int block_size = 256;
    int num_blocks = (output_size + block_size - 1) / block_size;

    hipLaunchKernelGGL(argmax_kernel, 
        num_blocks, block_size, 0, 0, 
        input.data_ptr<float>(), 
        output.data_ptr<int64_t>(), 
        reduction_size, 
        stride_d, 
        step_d, 
        output_size
    );

    return output;
}

