__global__ void fused_activation_kernel(const float* x, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= size) return;
    float val = x[idx];
    const float beta = 1.0f;
    const float threshold = 20.0f;
    float z = beta * val;

    float s;
    if (z > threshold) {
        s = z / beta;
    } else {
        s = log1pf(expf(z)) / beta;
    }
    float th = tanhf(s);
    out[idx] = val * th;
}

torch::Tensor fused_activation_rocm(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;
    auto stream = at::hip::getCurrentHIPStream();

    fused_activation_kernel<<<num_blocks, block_size, 0, stream>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), size
    );
    return out;
}

