#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_lse_gelu_add_kernel(const float* input, const float* residual, float* output, int num_batches) {
    int batch_idx = blockIdx.x;

    float max_val = -INFINITY;
    float sum_exp = 0.0f;

    for(int i = 0; i < 1; ++i) {  // Input has size (B, 1)
        float val = input[batch_idx];
        if(val > max_val) max_val = val;
    }

    sum_exp = expf(input[batch_idx] - max_val);

    float lse = max_val + logf(sum_exp);

    // GELU approximation matching PyTorch's default
    float gelu = 0.5f * lse * (1.0f + erff(lse / 1.41421356237f));

    // Add residual (original_x is size (B, in_features))
    for(int feat = threadIdx.x; feat < %FEAT_SIZE%; feat += blockDim.x) {
        output[batch_idx * %FEAT_SIZE% + feat] = gelu + residual[batch_idx * %FEAT_SIZE% + feat];
    }
}

torch::Tensor fused_lse_gelu_add_rocm(torch::Tensor input, torch::Tensor residual) {
    int num_batches = input.size(0);
    auto output = torch::empty_like(residual);

    const int block_size = 256;
    fused_lse_gelu_add_kernel<<<num_batches, block_size>>>(
        input.data_ptr<float>(),
        residual.data_ptr<float>(),
        output.data_ptr<float>(),
        num_batches
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv_transpose_2d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size,
    int in_channels, int out_channels,
    int input_h, int input_w,
    int output_h, int output_w,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    bool has_bias) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int elements_per_batch = out_channels * output_h * output_w;

    if (idx >= batch_size * elements_per_batch) return;

    int batch_idx = idx / elements_per_batch;
    int remaining = idx % elements_per_batch;

    int oc = remaining / (output_h * output_w);
    remaining %= (output_h * output_w);
    int oh = remaining / output_w;
    int ow = remaining % output_w;

    float sum = 0.0f;

    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kh = 0; kh < kernel_h; ++kh) {
            int ih = oh + padding_h - kh;
            if (ih < 0 || ih % stride_h != 0) continue;
            ih /= stride_h;
            if (ih >= input_h) continue;

            for (int kw = 0; kw < kernel_w; ++kw) {
                int iw = ow + padding_w - kw;
                if (iw < 0 || iw % stride_w != 0) continue;
                iw /= stride_w;
                if (iw >= input_w) continue;

                int input_idx = batch_idx * (in_channels * input_h * input_w)
                             + ic * (input_h * input_w)
                             + ih * input_w
                             + iw;

                int weight_idx = ic * (out_channels * kernel_h * kernel_w)
                              + oc * (kernel_h * kernel_w)
                              + kh * kernel_w
                              + kw;

                sum += input[input_idx] * weight[weight_idx];
            }
        }
    }

    if (has_bias) sum += bias[oc];
    output[idx] = sum;
}

torch::Tensor conv_transpose_2d_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int output_h,
    int output_w,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int padding_h,
    int padding_w) {

    auto batch_size = input.size(0);
    auto out_channels = weight.size(1);
    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(input.device());
    auto output = torch::zeros({batch_size, out_channels, output_h, output_w}, options);
    int total_elements = output.numel();

    dim3 block(256);
    dim3 grid((total_elements + block.x - 1) / block.x);

    const float* bias_ptr = bias ? bias->data_ptr<float>() : nullptr;

    hipLaunchKernelGGL(conv_transpose_2d_kernel, 
        grid, block, 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        input.size(1),
        out_channels,
        input.size(2),
        input.size(3),
        output_h,
        output_w,
        kernel_h,
        kernel_w,
        stride_h,
        stride_w,
        padding_h,
        padding_w,
        bool(bias)
    );

    return output;
}

