#include <ATen/hip/HIPContext.h>

__global__ void conv2d_rocm_kernel(
    const float* input, const float* weight, const float* bias, float* output,
    int batch_size, int in_channels, int out_channels,
    int input_h, int input_w, int output_h, int output_w,
    int kernel_h, int kernel_w, int stride_h, int stride_w,
    int pad_h, int pad_w, int dilation_h, int dilation_w
) {
    int w = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;
    int n = blockIdx.z / out_channels;
    int c = blockIdx.z % out_channels;

    if (n >= batch_size || c >= out_channels || h >= output_h || w >= output_w)
        return;

    float val = 0.0f;

    for(int ic = 0; ic < in_channels; ++ic) {
        for(int kh = 0; kh < kernel_h; ++kh) {
            for(int kw = 0; kw < kernel_w; ++kw) {
                int ih = h * stride_h - pad_h + kh * dilation_h;
                int iw = w * stride_w - pad_w + kw * dilation_w;

                if(ih >= 0 && ih < input_h && iw >= 0 && iw < input_w) {
                    float input_val = input[n * (in_channels*input_h*input_w) + 
                                         ic * (input_h*input_w) + 
                                         ih * input_w + iw];
                    float weight_val = weight[c * (in_channels*kernel_h*kernel_w) + 
                                          ic * (kernel_h*kernel_w) + 
                                          kh * kernel_w + kw];
                    val += input_val * weight_val;
                }
            }
        }
    }

    if(bias)
        val += bias[c];

    output[n * (out_channels*output_h*output_w) + 
           c * (output_h*output_w) + 
           h * output_w + w] = val;
}

torch::Tensor conv2d_rocm(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    std::vector<int64_t> output_shape, std::vector<int> stride,
    std::vector<int> padding, std::vector<int> dilation
) {
    auto output = torch::zeros(output_shape, input.options());

    dim3 block(16, 16);
    dim3 grid(
        (output_shape[3] + block.x - 1)/block.x,
        (output_shape[2] + block.y - 1)/block.y,
        output_shape[0] * output_shape[1]
    );

    hipLaunchKernelGGL(conv2d_rocm_kernel, grid, block, 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        input.size(0), input.size(1), output_shape[1],
        input.size(2), input.size(3),
        output_shape[2], output_shape[3],
        weight.size(2), weight.size(3),
        stride[0], stride[1],
        padding[0], padding[1],
        dilation[0], dilation[1]
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv_transpose1d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels, int kernel_size, 
    int input_length, int output_length, int stride, int padding, 
    int output_padding, int groups, int in_channels_per_group, 
    int out_channels_per_group) {

    int l_out = blockIdx.x * blockDim.x + threadIdx.x;
    int c_out = blockIdx.y * blockDim.y + threadIdx.y;
    int b = blockIdx.z;

    if (b >= batch_size || c_out >= out_channels || l_out >= output_length) return;

    int group = c_out / out_channels_per_group;
    int group_start_in = group * in_channels_per_group;
    float sum = 0.0f;

    for (int c_in_rel = 0; c_in_rel < in_channels_per_group; ++c_in_rel) {
        int c_in = group_start_in + c_in_rel;
        for (int k = 0; k < kernel_size; ++k) {
            int l_in_times_stride = l_out - k + padding;
            if (l_in_times_stride % stride != 0) continue;

            int l_in = l_in_times_stride / stride;
            if (l_in < 0 || l_in >= input_length) continue;

            float input_val = input[b * in_channels * input_length + c_in * input_length + l_in];
            float weight_val = weight[c_in * out_channels_per_group * kernel_size 
                                    + (c_out % out_channels_per_group) * kernel_size + k];
            sum += input_val * weight_val;
        }
    }

    if (bias) sum += bias[c_out];

    output[b * out_channels * output_length + c_out * output_length + l_out] = sum;
}

torch::Tensor conv_transpose1d_rocm(
    torch::Tensor input, torch::Tensor weight, torch::optional<torch::Tensor> bias,
    int stride, int padding, int output_padding, int groups) {

    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto input_length = input.size(2);
    int kernel_size = weight.size(2);
    int out_channels = weight.size(1) * groups;
    int output_length = (input_length - 1)*stride - 2*padding + kernel_size + output_padding;

    auto output = torch::zeros({batch_size, out_channels, output_length}, 
                              input.options());

    int in_channels_per_group = in_channels / groups;
    int out_channels_per_group = out_channels / groups;

    dim3 block(256, 1, 1);
    dim3 grid(
        (output_length + block.x - 1) / block.x,
        out_channels,
        batch_size
    );

    hipLaunchKernelGGL(conv_transpose1d_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias ? bias->data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels, kernel_size,
        input_length, output_length, stride, padding, output_padding,
        groups, in_channels_per_group, out_channels_per_group
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_ops_kernel(const float* linear_out, float subtract_val, float multiply_val, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = linear_out[idx];
        val = (val - subtract_val) * multiply_val;
        out[idx] = fmaxf(val, 0.0f);
    }
}

torch::Tensor fused_ops_rocm(torch::Tensor linear_out, float subtract_val, float multiply_val) {
    auto out = torch::empty_like(linear_out);
    int size = linear_out.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_ops_kernel<<<num_blocks, block_size>>>(
        linear_out.data_ptr<float>(), subtract_val, multiply_val, 
        out.data_ptr<float>(), size
    );

    return out;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_hardswish_relu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        float shifted = x + 3.0f;
        float clamped = fmaxf(0.0f, fminf(shifted, 6.0f));
        float hardswish_val = x * clamped / 6.0f;
        output[idx] = fmaxf(hardswish_val, 0.0f);
    }
}

torch::Tensor fused_hardswish_relu_rocm(torch::Tensor x) {
    auto output = torch::zeros_like(x);
    int size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    fused_hardswish_relu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void group_norm_kernel(
    const float* input, float* output,
    const float* weight, const float* bias,
    int n_batch,
    int n_chnls,
    int D, int H, int W,
    int groups, float epsilon) {

    extern __shared__ float smem[];
    int n = blockIdx.x;
    int g = blockIdx.y;
    int C_per_group = n_chnls / groups;
    int c_start = g * C_per_group;
    int c_end = c_start + C_per_group;

    float* sum = smem;
    float* sum_sq = &smem[blockDim.x];

    int tid = threadIdx.x;
    sum[tid] = 0.f;
    sum_sq[tid] = 0.f;

    int elements = C_per_group * D * H * W;
    int elems_per_thread = (elements + blockDim.x - 1) / blockDim.x;
    int start = tid * elems_per_thread;
    int end = min(start + elems_per_thread, elements);

    for(int i=start; i<end; ++i) {
        int c = c_start + (i / (D*H*W)) % C_per_group;
        int d = (i / (H*W)) % D;
        int h = (i / W) % H;
        int w = i % W;
        int idx = ((n * n_chnls + c) * D + d) * H * W + h * W + w;
        float val = input[idx];
        sum[tid] += val;
        sum_sq[tid] += val * val;
    }

    __syncthreads();

    for(int s=blockDim.x/2; s>0; s>>=1) {
        if(tid < s) {
            sum[tid] += sum[tid + s];
            sum_sq[tid] += sum_sq[tid + s];
        }
        __syncthreads();
    }

    float total_sum = sum[0];
    float total_sum_sq = sum_sq[0];
    float mean = total_sum / elements;
    float var = (total_sum_sq / elements) - (mean * mean);
    float inv_std = rsqrtf(var + epsilon);

    for(int i=start; i<end; ++i) {
        int c = c_start + (i / (D*H*W)) % C_per_group;
        int d = (i / (H*W)) % D;
        int h = (i / W) % H;
        int w = i % W;
        int idx = ((n * n_chnls + c) * D + d) * H * W + h * W + w;
        float normalized = (input[idx] - mean) * inv_std;
        output[idx] = normalized * weight[c] + bias[c];
    }
}

torch::Tensor group_norm_rocm(torch::Tensor input, 
                             torch::Tensor weight,
                             torch::Tensor bias,
                             int groups,
                             float epsilon) {
    auto output = torch::empty_like(input);
    auto sizes = input.sizes();
    int n_batch = sizes[0];
    int n_chnls = sizes[1];
    int D = sizes[2], H = sizes[3], W = sizes[4];

    dim3 grid(n_batch, groups);
    dim3 block(256);
    size_t smem = 2 * block.x * sizeof(float);

    hipLaunchKernelGGL(group_norm_kernel, grid, block, smem, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        n_batch, n_chnls, D, H, W, groups, epsilon);

    return output;
}
